"use client";

import { memo, useCallback, useEffect, useLayoutEffect, useRef, useState, type KeyboardEvent, type RefObject } from "react";
import {
  AgentProvider, useAgent, useAgentSelector, useAgentStatus, useLoadOlder, useMessages, useSend,
  type AssistantChatMessage, type ChatMessage, type ToolRenderers, type UserChatMessage,
} from "@camelai/run-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { AgentMarkdown } from "./agent-markdown";
import { AgentFile, AgentInputCard, AgentTool } from "./agent-parts";

export interface AgentChatProps {
  /** Your agent handler's route (createAgentHandler from @camelai/run/server). */
  endpoint: string;
  /** Which of the user's conversations. */
  thread?: string;
  /** Components for tool calls, by tool name (generative UI). */
  tools?: ToolRenderers;
  suggestions?: string[];
  placeholder?: string;
  className?: string;
}

/** A chat with the user's agent, in your shadcn theme. The code is yours: change anything. */
export function AgentChat({ endpoint, thread, tools, ...props }: AgentChatProps) {
  return (
    <AgentProvider endpoint={endpoint} thread={thread}>
      <AgentChatView tools={tools} {...props} />
    </AgentProvider>
  );
}

export function AgentChatView({ tools, suggestions = [], placeholder = "Message the agent…", className }: Omit<AgentChatProps, "endpoint" | "thread">) {
  const messages = useMessages();
  const { status, error } = useAgentStatus();
  const send = useSend();
  const { scroller, content, atBottom, toBottom } = useStickToBottom(messages);
  const { hasOlder, loading, loadOlder } = useLoadOlder();
  const waiting = status === "submitted" && !messages.some(message => message.role === "assistant" && message.streaming);
  return (
    <div className={cn("flex h-full min-h-0 flex-col bg-background text-foreground", className)}>
      <div className="relative min-h-0 flex-1">
        <div ref={scroller} role="log" aria-label="Conversation" aria-live="off" tabIndex={0} className="h-full overflow-y-auto">
          <div ref={content} className="mx-auto flex max-w-3xl flex-col gap-4 p-4">
            {hasOlder && <Button variant="outline" size="sm" className="self-center rounded-full" disabled={loading} onClick={() => void loadOlder()}>{loading ? "Loading…" : "Load earlier messages"}</Button>}
            {!messages.length && status !== "connecting" && (
              <div className="flex flex-col items-center gap-4 py-12 text-center">
                <p className="text-lg font-semibold">How can I help?</p>
                <div className="flex flex-wrap justify-center gap-2">
                  {suggestions.map(suggestion => <Button key={suggestion} variant="outline" size="sm" className="rounded-full" onClick={() => void send(suggestion)}>{suggestion}</Button>)}
                </div>
              </div>
            )}
            {messages.map(message => <Row key={message.id} message={message} tools={tools} />)}
            {waiting && <p className="animate-pulse text-sm text-muted-foreground" aria-hidden="true">Thinking…</p>}
          </div>
        </div>
        {!atBottom && <Button variant="outline" size="sm" className="absolute bottom-3 left-1/2 -translate-x-1/2 rounded-full shadow" onClick={() => toBottom(true)}>Jump to latest</Button>}
      </div>
      <Announcer />
      <Inputs />
      {status === "error" && error && <p role="alert" className="mx-auto mb-2 w-full max-w-3xl rounded-md border border-destructive px-3 py-2 text-sm text-destructive">{error.message}</p>}
      <Composer placeholder={placeholder} />
    </div>
  );
}

const Row = memo(function Row({ message, tools }: { message: ChatMessage; tools?: ToolRenderers }) {
  return message.role === "user" ? <UserBubble message={message} /> : <AssistantTurn message={message} tools={tools} />;
});

/** A sub-agent's notification or message: the runtime wrote it, so it is a notice, never the user's bubble. */
function AgentNotice({ message }: { message: UserChatMessage }) {
  const notice = message.agent!;
  const title = notice.kind === "message" ? (notice.name === "parent" ? "Message from the parent agent" : `Message from sub-agent ${notice.name}`)
    : `Sub-agent ${notice.name} ${notice.status === "completed" ? "finished" : notice.status === "input_required" ? "is waiting for input" : notice.status ?? "finished"}`;
  return (
    <details className="rounded-lg border px-3 py-2 text-sm" data-status={notice.status}>
      <summary className={cn("cursor-pointer text-muted-foreground", (notice.status === "failed" || notice.status === "aborted") && "text-destructive")}>{title}</summary>
      <div className="mt-2"><AgentMarkdown text={message.text} streaming={false} /></div>
    </details>
  );
}

const UserBubble = memo(function UserBubble({ message }: { message: UserChatMessage }) {
  const chat = useAgent();
  if (message.agent) return <AgentNotice message={message} />;
  return (
    <div className="flex flex-col items-end gap-1">
      {message.from?.name && <span className="text-xs text-muted-foreground">{message.from.name}</span>}
      <div className={cn("max-w-[85%] whitespace-pre-wrap break-words rounded-2xl bg-secondary px-4 py-2 text-sm text-secondary-foreground", message.status === "sending" && "opacity-70")}>{message.text}</div>
      {message.status === "failed" && (
        <p role="alert" className="text-xs text-destructive">
          {message.error?.message ?? "Not sent."}{" "}
          <button type="button" className="underline" onClick={() => void chat.retry(message.id)}>Retry</button>
        </p>
      )}
    </div>
  );
});

const AssistantTurn = memo(function AssistantTurn({ message, tools }: { message: AssistantChatMessage; tools?: ToolRenderers }) {
  const last = message.parts.at(-1);
  return (
    <div className="flex flex-col gap-2">
      {message.parts.map(part => {
        switch (part.type) {
          case "text": return <AgentMarkdown key={part.id} text={part.text} streaming={message.streaming && part === last} />;
          case "reasoning": return part.redacted ? null : (
            <details key={part.id} className="rounded-md border text-sm text-muted-foreground">
              <summary className="cursor-pointer px-3 py-2">{part.streaming ? "Thinking…" : "Reasoning"}</summary>
              <p className="whitespace-pre-wrap px-3 pb-3">{part.text}</p>
            </details>
          );
          case "tool": return <AgentTool key={part.id} part={part} tools={tools} />;
          case "file": return <AgentFile key={part.id} part={part} />;
          default: return null;
        }
      })}
      {message.stopReason === "aborted" && <p className="text-xs text-muted-foreground">Stopped.</p>}
      {message.stopReason === "error" && <p className="text-xs text-destructive">{message.error ?? "The reply failed."}</p>}
    </div>
  );
});

/** Inputs whose call is not on screen. */
function Inputs() {
  const loose = useAgentSelector(snapshot => {
    const shown = new Set(snapshot.messages.flatMap(message => message.role === "assistant" ? message.parts.flatMap(part => part.type === "tool" && part.input ? [part.input.id] : []) : []));
    return snapshot.inputs.filter(input => !shown.has(input.id));
  }, { equal: (a, b) => a.length === b.length && a.every((input, at) => input === b[at]) });
  if (!loose.length) return null;
  return <div className="mx-auto mb-2 w-full max-w-3xl space-y-2 px-4">{loose.map(input => <AgentInputCard key={input.id} input={input} />)}</div>;
}

function Composer({ placeholder }: { placeholder: string }) {
  const send = useSend();
  const { isRunning, stop } = useAgentStatus();
  const [text, setText] = useState("");
  const submit = () => {
    const message = text.trim();
    if (!message) { if (isRunning) void stop(); return; }
    setText("");
    void send(message);
  };
  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) { event.preventDefault(); submit(); }
    else if (event.key === "Escape" && isRunning) { event.preventDefault(); void stop(); }
  };
  const stopping = isRunning && !text.trim();
  return (
    <form className="mx-auto mb-4 flex w-[calc(100%-2rem)] max-w-3xl items-end gap-2 rounded-2xl border bg-background p-2 pl-4 focus-within:ring-1 focus-within:ring-ring" onSubmit={event => { event.preventDefault(); submit(); }}>
      <textarea
        rows={1} value={text} placeholder={placeholder} aria-label="Message"
        className="max-h-48 min-h-9 flex-1 resize-none bg-transparent py-2 text-sm outline-none [field-sizing:content] placeholder:text-muted-foreground"
        onChange={event => setText(event.currentTarget.value)} onKeyDown={onKeyDown} />
      <Button type="submit" size="icon" className="size-9 shrink-0 rounded-full" disabled={!stopping && !text.trim()} aria-label={stopping ? "Stop" : "Send"}>
        {stopping ? <span className="size-3 rounded-sm bg-current" /> : <span aria-hidden="true">↑</span>}
      </Button>
    </form>
  );
}

/** Says "responding", then the finished reply, to screen readers (the log itself is not read token by token). */
function Announcer() {
  const status = useAgentSelector(snapshot => snapshot.status);
  const reply = useAgentSelector(snapshot => {
    const last = snapshot.messages.at(-1);
    return last?.role === "assistant" && !last.streaming ? last.parts.flatMap(part => part.type === "text" ? [part.text] : []).join("\n").slice(0, 1000) : "";
  });
  const [text, setText] = useState("");
  const previous = useRef(status);
  useEffect(() => {
    const was = previous.current;
    previous.current = status;
    if (status === "streaming" && was !== "streaming") setText("The assistant is responding.");
    else if (status === "input_required" && was !== "input_required") setText("The assistant needs your input.");
    else if (status === "ready" && (was === "streaming" || was === "submitted") && reply) setText(`The assistant replied: ${reply}`);
  }, [status, reply]);
  return <div role="status" aria-live="polite" aria-atomic="true" className="sr-only">{text}</div>;
}

/** Follow new content while at the bottom; stay put (and offer a way back) once scrolled up. */
function useStickToBottom(messages: ChatMessage[]): { scroller: RefObject<HTMLDivElement | null>; content: RefObject<HTMLDivElement | null>; atBottom: boolean; toBottom(smooth?: boolean): void } {
  const scroller = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const bottom = useRef(true);
  const [atBottom, setAtBottom] = useState(true);
  const toBottom = useCallback((smooth = false) => {
    const element = scroller.current;
    if (!element) return;
    element.scrollTo({ top: element.scrollHeight, behavior: smooth ? "smooth" : "auto" });
    bottom.current = true;
    setAtBottom(true);
  }, []);
  useEffect(() => {
    const element = scroller.current;
    if (!element) return;
    const onScroll = () => {
      bottom.current = element.scrollHeight - element.scrollTop - element.clientHeight < 48;
      setAtBottom(bottom.current);
    };
    element.addEventListener("scroll", onScroll, { passive: true });
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(() => { if (bottom.current) toBottom(); });
    if (content.current) observer?.observe(content.current);
    return () => { element.removeEventListener("scroll", onScroll); observer?.disconnect(); };
  }, [toBottom]);
  const last = messages.at(-1);
  useLayoutEffect(() => { if (last?.role === "user") toBottom(); }, [last?.id, last?.role, toBottom]);
  return { scroller, content, atBottom, toBottom };
}

"use client";

import { memo, useCallback, useEffect, useState, type FormEvent } from "react";
import { useAgent, useToolRendererFor, type ChatInput, type FilePart, type InputAnswer, type InputValue, type ToolPart, type ToolRenderers } from "@camelai/run-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

const localName = (name: string) => name.includes("__") ? name.slice(name.lastIndexOf("__") + 2) : name;
const clip = (text: string, max = 4000) => text.length > max ? `${text.slice(0, max)}…` : text;
const pretty = (value: unknown) => { try { return JSON.stringify(value, null, 2); } catch { return String(value); } };

/** A tool call: your component for it (generative UI), what it waits on, or a collapsible card. */
export const AgentTool = memo(function AgentTool({ part, tools }: { part: ToolPart; tools?: ToolRenderers }) {
  const chat = useAgent();
  const exact = useToolRendererFor(part.name, tools);
  const local = useToolRendererFor(localName(part.name), tools);
  const Renderer = exact ?? local;
  if (Renderer) {
    const answer = (value: InputValue | InputAnswer) => part.input ? chat.answer(part.input, value) : Promise.reject(new Error(`${part.name} is not waiting for an answer`));
    return <Renderer part={part} name={part.name} args={part.args} state={part.state} result={part.result} progress={part.progress} input={part.input} answer={answer} />;
  }
  if (part.input) return <AgentInputCard input={part.input} />;
  const name = localName(part.name);
  const label = part.state === "done" ? `Used ${name}` : part.state === "error" ? `${name} failed` : `Running ${name}…`;
  return (
    <details className="group rounded-md border text-sm">
      <summary className="flex cursor-pointer list-none items-center gap-2 px-3 py-2 text-muted-foreground [&::-webkit-details-marker]:hidden">
        <span aria-hidden="true" className={cn("size-2 rounded-full", part.state === "done" ? "bg-green-500" : part.state === "error" ? "bg-destructive" : "animate-pulse bg-muted-foreground")} />
        <span>{label}</span>
        {part.progress?.message && <span className="truncate text-xs">{part.progress.message}</span>}
      </summary>
      <div className="space-y-2 px-3 pb-3">
        <pre className="max-h-64 overflow-auto rounded bg-muted p-2 font-mono text-xs"><code>{typeof part.args.code === "string" ? part.args.code : pretty(part.args)}</code></pre>
        {part.result && <pre className="max-h-64 overflow-auto rounded bg-muted p-2 font-mono text-xs"><code>{clip(typeof part.result.data === "object" && part.result.data !== null ? pretty(part.result.data) : part.result.text)}</code></pre>}
      </div>
    </details>
  );
});

interface Question { question: string; header?: string; options?: { label: string; description?: string }[]; multiSelect?: boolean; allowOther?: boolean }

/** What the agent waits on: an approval, questions, a form, or a page to visit. */
export const AgentInputCard = memo(function AgentInputCard({ input }: { input: ChatInput }) {
  const chat = useAgent();
  const answer = (value: InputValue | InputAnswer) => { void chat.answer(input, value); };
  const busy = input.answering;
  return (
    <div className="space-y-3 rounded-lg border p-4 text-sm" aria-busy={busy || undefined}>
      {input.kind === "approval" && (
        <>
          <p className="font-medium">{input.message}</p>
          {(input.detail.argumentsPreview ?? input.detail.arguments) && <pre className="max-h-48 overflow-auto rounded bg-muted p-2 font-mono text-xs">{clip(input.detail.argumentsPreview ?? JSON.stringify(input.detail.arguments, null, 2), 2000)}</pre>}
          <div className="flex gap-2">
            <Button size="sm" disabled={busy} onClick={() => answer(true)}>Approve</Button>
            <Button size="sm" variant="outline" disabled={busy} onClick={() => answer(false)}>Deny</Button>
          </div>
        </>
      )}
      {input.kind === "question" && <Questions questions={(input.detail.questions ?? []) as Question[]} busy={busy} onAnswer={answer} />}
      {input.kind === "form" && <FormFields input={input} busy={busy} onAnswer={answer} />}
      {input.kind === "url" && (
        <>
          <p className="font-medium">{input.message}</p>
          <div className="flex flex-wrap gap-2">
            {typeof input.detail.url === "string" && input.detail.url.startsWith("https://") && (
              <a href={input.detail.url} target="_blank" rel="noopener noreferrer" className="inline-flex h-8 items-center rounded-md bg-primary px-3 text-primary-foreground">Open {String(input.detail.origin ?? "")}</a>
            )}
            <Button size="sm" variant="outline" disabled={busy} onClick={() => answer(true)}>Done</Button>
            <Button size="sm" variant="ghost" disabled={busy} onClick={() => answer(false)}>Cancel</Button>
          </div>
        </>
      )}
      {input.error && <p role="alert" className="text-destructive">{input.error.message}</p>}
    </div>
  );
});

function Questions({ questions, busy, onAnswer }: { questions: Question[]; busy: boolean; onAnswer(value: InputValue): void }) {
  const [chosen, setChosen] = useState<Record<string, string[]>>({});
  const [other, setOther] = useState<Record<string, string>>({});
  const valueOf = (question: Question) => {
    const own = other[question.question]?.trim();
    const picked = chosen[question.question] ?? [];
    if (question.multiSelect) return own ? [...picked, own] : picked;
    return picked[0] ?? own;
  };
  const complete = questions.every(question => { const value = valueOf(question); return Array.isArray(value) ? value.length > 0 : !!value; });
  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (complete) onAnswer(Object.fromEntries(questions.map(question => [question.question, valueOf(question)!])));
  };
  return (
    <form onSubmit={submit} className="space-y-4">
      {questions.map(question => (
        <fieldset key={question.question} disabled={busy} className="space-y-2">
          <legend className="mb-2 font-medium">{question.question}</legend>
          {(question.options ?? []).map(option => (
            <label key={option.label} className="flex cursor-pointer items-start gap-2 rounded-md border px-3 py-2 has-[:checked]:border-primary">
              <input
                type={question.multiSelect ? "checkbox" : "radio"} name={question.question} className="mt-1 accent-primary"
                checked={chosen[question.question]?.includes(option.label) ?? false}
                onChange={event => {
                  const checked = event.currentTarget.checked;
                  setChosen(current => ({ ...current, [question.question]: question.multiSelect ? checked ? [...current[question.question] ?? [], option.label] : (current[question.question] ?? []).filter(label => label !== option.label) : [option.label] }));
                  if (!question.multiSelect) setOther(current => ({ ...current, [question.question]: "" }));
                }} />
              <span>{option.label}{option.description && <span className="block text-xs text-muted-foreground">{option.description}</span>}</span>
            </label>
          ))}
          {question.allowOther !== false && (
            <input
              aria-label={`Other answer: ${question.question}`} placeholder={question.options?.length ? "Other…" : "Your answer"}
              className="h-9 w-full rounded-md border bg-transparent px-3" value={other[question.question] ?? ""}
              onChange={event => {
                const value = event.currentTarget.value;
                setOther(current => ({ ...current, [question.question]: value }));
                if (!question.multiSelect && value) setChosen(current => ({ ...current, [question.question]: [] }));
              }} />
          )}
        </fieldset>
      ))}
      <Button type="submit" size="sm" disabled={!complete || busy}>Submit</Button>
    </form>
  );
}

function FormFields({ input, busy, onAnswer }: { input: ChatInput; busy: boolean; onAnswer(value: InputValue | InputAnswer): void }) {
  const schema = (input.detail.requestedSchema ?? {}) as { properties?: Record<string, { type?: string; title?: string; description?: string; enum?: unknown[] }>; required?: string[] };
  const fields = Object.entries(schema.properties ?? {});
  const [values, setValues] = useState<Record<string, string | boolean>>({});
  const submit = (event: FormEvent) => {
    event.preventDefault();
    onAnswer(Object.fromEntries(fields.flatMap(([name, field]) => {
      const value = values[name];
      if (value === undefined || value === "") return field.type === "boolean" ? [[name, false]] : [];
      return [[name, field.type === "number" || field.type === "integer" ? Number(value) : value]];
    })));
  };
  return (
    <form onSubmit={submit} className="space-y-3">
      <p className="font-medium">{input.message}</p>
      {fields.map(([name, field]) => (
        <label key={name} className="block space-y-1">
          <span className="text-sm">{field.title ?? name}{schema.required?.includes(name) ? " *" : ""}</span>
          {field.type === "boolean" ? (
            <input type="checkbox" disabled={busy} checked={values[name] === true} onChange={event => { const checked = event.currentTarget.checked; setValues(current => ({ ...current, [name]: checked })); }} className="ml-2 accent-primary" />
          ) : field.enum ? (
            <select disabled={busy} required={schema.required?.includes(name)} value={String(values[name] ?? "")} onChange={event => { const value = event.currentTarget.value; setValues(current => ({ ...current, [name]: value })); }} className="h-9 w-full rounded-md border bg-transparent px-2">
              <option value="" disabled>Choose…</option>
              {field.enum.map(option => <option key={String(option)} value={String(option)}>{String(option)}</option>)}
            </select>
          ) : (
            <input disabled={busy} required={schema.required?.includes(name)} type={field.type === "number" || field.type === "integer" ? "number" : "text"} value={String(values[name] ?? "")}
              onChange={event => { const value = event.currentTarget.value; setValues(current => ({ ...current, [name]: value })); }} className="h-9 w-full rounded-md border bg-transparent px-3" />
          )}
          {field.description && <span className="block text-xs text-muted-foreground">{field.description}</span>}
        </label>
      ))}
      <div className="flex gap-2">
        <Button type="submit" size="sm" disabled={busy}>Submit</Button>
        <Button type="button" size="sm" variant="ghost" disabled={busy} onClick={() => onAnswer({ action: "decline" })}>Skip</Button>
      </div>
    </form>
  );
}

/** A file the agent handed over: an image inline, anything else as a download (a signed link through your handler). */
export const AgentFile = memo(function AgentFile({ part }: { part: FilePart }) {
  const chat = useAgent();
  const [url, setUrl] = useState(part.url);
  const refresh = useCallback(() => { chat.fileUrl(part.path).then(setUrl, () => {}); }, [chat, part.path]);
  useEffect(() => { if (part.url) setUrl(part.url); else refresh(); }, [part.url, refresh]);
  const image = part.contentType?.startsWith("image/") && part.contentType !== "image/svg+xml";
  return (
    <figure className="max-w-sm space-y-1">
      {image && url && <img src={url} alt={part.caption ?? part.name} className="max-h-80 rounded-md border" loading="lazy" />}
      <a href={url} download={part.name} target="_blank" rel="noopener noreferrer" onMouseEnter={refresh} onFocus={refresh}
        className="flex flex-col rounded-md border px-3 py-2 text-sm hover:bg-muted">
        <span className="font-medium">{part.name}</span>
        <span className="text-xs text-muted-foreground">{part.caption ?? "Download"}</span>
      </a>
    </figure>
  );
});

"use client";

import { memo, useMemo, type ReactNode } from "react";
import { parseMarkdown, type Block, type Inline } from "@camelai/run/markdown";
import { cn } from "@/lib/utils";

/**
 * The agent's markdown, rendered with elements (never HTML): only http(s) and mailto links, images as
 * links (loading an image the model chose tells its server about the reader), and tolerant of text
 * that is still streaming. Unchanged blocks are not rendered again.
 */
export const AgentMarkdown = memo(function AgentMarkdown({ text, streaming = false, className }: { text: string; streaming?: boolean; className?: string }) {
  // Should parsing ever fail, the text shows as it is: a reply always renders.
  const blocks = useMemo<Block[]>(() => {
    try { return parseMarkdown(text, { streaming }); }
    catch { return [{ type: "paragraph", children: [{ type: "text", text }], raw: text }]; }
  }, [text, streaming]);
  return (
    <div className={cn("space-y-3 break-words text-sm leading-relaxed", className)}>
      {blocks.map((block, at) => <MarkdownBlock key={at} block={block} open={streaming && at === blocks.length - 1} />)}
    </div>
  );
});

const MarkdownBlock = memo(function MarkdownBlock({ block }: { block: Block; open?: boolean }) {
  switch (block.type) {
    case "paragraph": return <p><Inlines nodes={block.children} /></p>;
    case "heading": {
      const size = ["text-xl", "text-lg", "text-base", "text-sm", "text-sm", "text-sm"][block.level - 1];
      const Tag = `h${block.level}` as "h2";
      return <Tag className={cn("font-semibold tracking-tight", size)}><Inlines nodes={block.children} /></Tag>;
    }
    case "code": return (
      <div className="overflow-hidden rounded-md border bg-muted">
        {block.lang && <div className="border-b px-3 py-1 text-xs text-muted-foreground">{block.lang}</div>}
        <pre className="overflow-x-auto p-3 font-mono text-xs leading-normal"><code>{block.text}</code></pre>
      </div>
    );
    case "blockquote": return <blockquote className="space-y-3 border-l-2 pl-3 text-muted-foreground">{block.children.map((child, at) => <MarkdownBlock key={at} block={child} />)}</blockquote>;
    case "list": {
      const items = block.items.map((item, at) => (
        <li key={at}>{item.length === 1 && item[0].type === "paragraph" ? <Inlines nodes={item[0].children} /> : item.map((child, index) => <MarkdownBlock key={index} block={child} />)}</li>
      ));
      return block.ordered
        ? <ol start={block.start === 1 ? undefined : block.start} className="list-decimal space-y-1 pl-5">{items}</ol>
        : <ul className="list-disc space-y-1 pl-5">{items}</ul>;
    }
    case "table": return (
      <div className="overflow-x-auto">
        <table className="w-auto border-collapse text-sm">
          <thead><tr>{block.head.map((cell, at) => <th key={at} className="border bg-muted px-3 py-1 text-left font-medium" style={block.align[at] ? { textAlign: block.align[at]! } : undefined}><Inlines nodes={cell} /></th>)}</tr></thead>
          <tbody>{block.rows.map((row, index) => <tr key={index}>{row.map((cell, at) => <td key={at} className="border px-3 py-1" style={block.align[at] ? { textAlign: block.align[at]! } : undefined}><Inlines nodes={cell} /></td>)}</tr>)}</tbody>
        </table>
      </div>
    );
    case "hr": return <hr className="border-border" />;
  }
}, (a, b) => a.block.raw === b.block.raw && a.block.type === b.block.type && a.open === b.open);

function Inlines({ nodes }: { nodes: Inline[] }) {
  return <>{nodes.map((node, at) => <InlineNode key={at} node={node} />)}</>;
}

function InlineNode({ node }: { node: Inline }): ReactNode {
  switch (node.type) {
    case "text": return node.text;
    case "break": return <br />;
    case "code": return <code className="rounded bg-muted px-1 py-0.5 font-mono text-[0.85em]">{node.text}</code>;
    case "strong": return <strong className="font-semibold"><Inlines nodes={node.children} /></strong>;
    case "em": return <em><Inlines nodes={node.children} /></em>;
    case "del": return <del><Inlines nodes={node.children} /></del>;
    case "link": return <a href={node.href} target="_blank" rel="noopener noreferrer nofollow" className="underline underline-offset-2"><Inlines nodes={node.children} /></a>;
    case "image": return <a href={node.src} target="_blank" rel="noopener noreferrer nofollow" className="underline underline-offset-2">{node.alt || node.src}</a>;
  }
}
